<?php
declare(strict_types=1); require_once __DIR__.'/../bootstrap.php'; Auth::requireRole('admin');
require_once DOGOFLOW_ROOT . '/core/security/AdminAudit.php';
$pdo=db();
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['_csrf'] ?? null); $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT) ?: 0; try { $q=$pdo->prepare('SELECT id,name,seller_id,status FROM products WHERE id=?'); $q->execute([$id]); $product=$q->fetch(PDO::FETCH_ASSOC); if(!$product) throw new RuntimeException('Product not found'); $pdo->beginTransaction(); $pdo->prepare('DELETE FROM product_images WHERE product_id=?')->execute([$id]); $pdo->prepare('DELETE FROM product_categories WHERE product_id=?')->execute([$id]); dogoflow_admin_audit($pdo,'product_removed','product',(int)$product['id'],['name'=>$product['name'],'seller_id'=>$product['seller_id'],'status'=>$product['status']]); $pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]); $pdo->commit(); flash('success','Product removed successfully.'); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); error_log('Admin product removal failed: '.$e->getMessage()); flash('error','Could not remove this product. It may be referenced by an existing order.'); } header('Location: '.url('/admin/products.php'),true,303); exit; }
$notice=flash('success'); $error=flash('error');
$products=db()->query('SELECT p.id,p.name,p.price,p.stock,p.status,p.created_at,u.name seller_name FROM products p LEFT JOIN users u ON u.id=p.seller_id ORDER BY p.id DESC LIMIT 200')->fetchAll();$active='products';$pageTitle='Products';$pageDescription='Marketplace catalogue and inventory overview';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products · DogoFlow Admin</title><link rel="icon" href="<?=url('/assets/images/favicon-32.png')?>"><link rel="stylesheet" href="<?=url('/assets/css/app.css')?>">
    <link rel="stylesheet" href="<?=url('/assets/css/admin.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/admin-ui-consistency.css')?>"><link rel="stylesheet" href="<?=url('/assets/css/responsive.css')?>"></head><body class="admin-shell"><?php require __DIR__.'/../partials/admin_sidebar.php'; ?><section class="admin-main"><?php require __DIR__.'/../partials/admin_topbar.php'; ?><main class="admin-content"><div class="page-heading"><div><h1>Products</h1><p>Review and moderate products currently listed on DogoFlow.</p></div></div><?php if($notice):?><div class="alert success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><div class="toolbar-df"><div class="search-df">🔎<input id="tableSearch" type="search" placeholder="Search products or sellers..."></div></div><article class="panel-df"><div class="table-wrap-df"><table class="table-df" id="dataTable"><thead><tr><th>Product</th><th>Seller</th><th>Price</th><th>Stock</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?=e($p['name'])?></strong></td><td><?=e($p['seller_name']??'Platform')?></td><td><strong>GH₵ <?=number_format((float)$p['price'],2)?></strong></td><td><?= (int)$p['stock']?></td><td><span class="badge-df <?=$p['status']==='active'?'success':($p['status']==='rejected'?'danger':'warning')?>"><?=e($p['status'])?></span></td><td><?=e(date('d M Y',strtotime($p['created_at'])))?></td><td><form method="post" onsubmit="return confirm('Permanently remove this product? Existing order references may prevent removal.');"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="btn-df danger btn-sm" type="submit">Remove</button></form></td></tr><?php endforeach;if(!$products):?><tr><td colspan="7"><div class="empty-df">No products have been listed yet.</div></td></tr><?php endif;?></tbody></table></div></article></main></section><script>document.getElementById('tableSearch')?.addEventListener('input',function(){const q=this.value.toLowerCase();document.querySelectorAll('#dataTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none');});</script></body></html>
